import{b as i,O as a,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"远程仓库","description":"","frontmatter":{},"headers":[],"relativePath":"git/basics/remote/index.md","filePath":"Git操作手册/2.基础操作/06.远程仓库.md","lastUpdated":1782199931000}'),h={name:"git/basics/remote/index.md"};function n(l,s,p,d,k,o){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="远程仓库" tabindex="-1">远程仓库 <a class="header-anchor" href="#远程仓库" aria-label="Permalink to &quot;远程仓库&quot;">​</a></h1><blockquote><p>git remote / git push / git fetch / git pull，和 GitHub 顺畅协作</p></blockquote><h2 id="你的本地仓库关联了哪些远程" tabindex="-1">你的本地仓库关联了哪些远程 <a class="header-anchor" href="#你的本地仓库关联了哪些远程" aria-label="Permalink to &quot;你的本地仓库关联了哪些远程&quot;">​</a></h2><p><code>git remote</code> 查看关联的远程仓库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 只显示名字</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># origin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 显示名字 + 完整地址</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># origin  git@github.com:yychuiyan/my-project.git (fetch)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># origin  git@github.com:yychuiyan/my-project.git (push)</span></span></code></pre></div><p><code>origin</code> 是克隆或关联时自动起的默认名称——看到它就知道是远程仓库。</p><h3 id="删除或改名" tabindex="-1">删除或改名 <a class="header-anchor" href="#删除或改名" aria-label="Permalink to &quot;删除或改名&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 删除关联</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-name</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 重命名</span></span></code></pre></div><h2 id="推送-git-push" tabindex="-1">推送：git push <a class="header-anchor" href="#推送-git-push" aria-label="Permalink to &quot;推送：git push&quot;">​</a></h2><p>把本地提交同步到 GitHub：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 推到默认远程分支（前提：设过 -u 追踪）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 指定远程和分支</span></span></code></pre></div><p>第一次 push 某个分支时，用 <code>-u</code> 建立追踪——之后直接 <code>git push</code> 就行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span></span></code></pre></div><h3 id="push-被拒怎么办" tabindex="-1">push 被拒怎么办 <a class="header-anchor" href="#push-被拒怎么办" aria-label="Permalink to &quot;push 被拒怎么办&quot;">​</a></h3><p>如果你 push 的时候别人已经推了新提交，你会看到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>! [rejected]  master -&gt; master (fetch first)</span></span></code></pre></div><p>这说明远程有你本地没有的新提交。正确做法是先拉取、合并、再推：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 拉取 + 合并</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 解决可能的冲突</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 再推</span></span></code></pre></div><h3 id="强制推送要慎用" tabindex="-1">强制推送要慎用 <a class="header-anchor" href="#强制推送要慎用" aria-label="Permalink to &quot;强制推送要慎用&quot;">​</a></h3><p>不要用 <code>git push --force</code>，它会直接覆盖远程历史——同事的提交可能被你冲掉。用 <code>--force-with-lease</code> 替代：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-with-lease</span></span></code></pre></div><p>它会在推送前检查：远程有没有你不知道的新提交？如果有，拒绝推送，保护同事的代码不被覆盖。</p><h2 id="拉取前先看看-git-fetch" tabindex="-1">拉取前先看看：git fetch <a class="header-anchor" href="#拉取前先看看-git-fetch" aria-label="Permalink to &quot;拉取前先看看：git fetch&quot;">​</a></h2><p><code>git fetch</code> 从远程下载最新数据，但<strong>不会自动合并到你的工作区</strong>——只是让你&quot;先看看&quot;：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span></span></code></pre></div><p>执行后可以对比本地和远程的差异：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/master</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 看远程多了哪些提交</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/master</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 看远程改了什么</span></span></code></pre></div><p>确认没问题了，再合并：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/master</span></span></code></pre></div><h2 id="拉取并合并-git-pull" tabindex="-1">拉取并合并：git pull <a class="header-anchor" href="#拉取并合并-git-pull" aria-label="Permalink to &quot;拉取并合并：git pull&quot;">​</a></h2><p><code>git pull</code> 是日常最常用的拉取命令，它等于 <code>fetch + merge</code> 二合一：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 等同于</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/master</span></span></code></pre></div><p>大部分时候你直接用 <code>git pull</code>，一步到位。当你对远程改动不确定时，用 <code>git fetch</code> 先看一眼再合并，更安全。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>远程操作的四个日常命令：</p><table tabindex="0"><thead><tr><th>命令</th><th>做什么</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>git remote -v</code></td><td>查看关联了哪些远程</td><td>换电脑、排查连接问题</td></tr><tr><td><code>git push</code></td><td>本地提交推到远程</td><td>每次 commit 完</td></tr><tr><td><code>git fetch</code></td><td>下载远程更新但不合并</td><td>想先看看别人改了什么</td></tr><tr><td><code>git pull</code></td><td>下载并合并（fetch+merge）</td><td>每次开始干活前</td></tr></tbody></table><blockquote><p>💡 每天开工第一件事：<code>git pull</code>。每天收工最后一件：<code>git push</code>。养成习惯，冲突和丢代码的概率大幅降低。</p></blockquote><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>用 <code>git remote -v</code> 查看当前仓库的远程地址</li><li>在 GitHub 上直接修改一个文件并提交，然后在本地用 <code>git fetch</code> 拉取，用 <code>git log origin/master</code> 看远程多了什么，再用 <code>git merge</code> 合并</li><li>在本地新建一个分支，用 <code>git push -u origin 分支名</code> 推送，去 GitHub 确认分支出现了</li><li>试试 <code>git push --force-with-lease</code> 和 <code>git push --force</code> 的区别（在一个测试仓库里，注意别在正式项目用 --force）</li></ol>`,39)])])}const g=i(h,[["render",n]]);export{c as __pageData,g as default};
